# 아직 적용 전이라 테스트로 계층을 확인한다
@Test
void hierarchy() {
    assertThat(DataAccessException.class.getSuperclass())
            .isEqualTo(NestedRuntimeException.class);
    // NestedRuntimeException extends RuntimeException  -> 언체크

    assertThat(DuplicateKeyException.class.getSuperclass())
            .isEqualTo(DataIntegrityViolationException.class);

    assertThat(CannotAcquireLockException.class.getSuperclass())
            .isEqualTo(PessimisticLockingFailureException.class);
    // PessimisticLockingFailureException extends ConcurrencyFailureException
    // ConcurrencyFailureException extends TransientDataAccessException
}

